namespace sv_789bf35399454e74bc5dd97ad029cd34.Client.Models;

public class Shipment
{
    public required string TrackingNumber { get; set; }
    public required string Status { get; set; }
    public required string Location { get; set; }
    public DateTimeOffset? EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = [];
}

public class StatusUpdate
{
    public required string Description { get; set; }
    public required string Location { get; set; }
    public DateTimeOffset Timestamp { get; set; }
}

using sv_789bf35399454e74bc5dd97ad029cd34.Client.Models;

namespace sv_789bf35399454e74bc5dd97ad029cd34.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_789bf35399454e74bc5dd97ad029cd34.Client.Models;
using sv_789bf35399454e74bc5dd97ad029cd34.Client.Services;

namespace sv_789bf35399454e74bc5dd97ad029cd34.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(2),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Description = "Package picked up",
                    Location = "Los Angeles, CA",
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-3)
                },
                new StatusUpdate
                {
                    Description = "Arrived at sorting facility",
                    Location = "Phoenix, AZ",
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-2)
                },
                new StatusUpdate
                {
                    Description = "Departed facility",
                    Location = "Memphis, TN",
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-1)
                }
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(-1),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Description = "Package picked up",
                    Location = "Chicago, IL",
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-5)
                },
                new StatusUpdate
                {
                    Description = "In transit",
                    Location = "Columbus, OH",
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-3)
                },
                new StatusUpdate
                {
                    Description = "Out for delivery",
                    Location = "New York, NY",
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-1)
                },
                new StatusUpdate
                {
                    Description = "Delivered",
                    Location = "New York, NY",
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-1).AddHours(4)
                }
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(5),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Description = "Label created",
                    Location = "Seattle, WA",
                    Timestamp = DateTimeOffset.UtcNow.AddHours(-6)
                }
            ]
        }
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found with tracking number '{trackingNumber}'.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_789bf35399454e74bc5dd97ad029cd34.Client.Models
@using sv_789bf35399454e74bc5dd97ad029cd34.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracker</h3>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            @if (_shipment.EstimatedDelivery.HasValue)
            {
                <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.Value.LocalDateTime.ToString("f")</p>
            }
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h5>Tracking History</h5>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Date</th>
                    <th>Location</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.LocalDateTime.ToString("g")</td>
                        <td>@update.Location</td>
                        <td>@update.Description</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request before starting a new one.
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();

        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — silently abandon.
            return;
        }
        catch (TimeoutException)
        {
            Logger.LogError("Timeout while loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError("Timeout while loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

